assertAll("overloads called from Java",
() -> System.out.println(OverloadsKt.addProduct("Name", ., "Desc")),
() -> System.out.println(OverloadsKt.addProduct("Name", .)),
() -> System.out.println(OverloadsKt.addProduct("Name"))
